// Process and structure the incoming table order & customer CRM data
const body = $input.item.json.body || $input.item.json;

const orderSummary = {
  orderId: body.id || 'KOT-' + Math.floor(100 + Math.random() * 900),
  table: body.table || '4',
  customerName: body.customerName || 'Guest',
  customerPhone: body.customerPhone || 'N/A',
  itemsCount: body.items ? body.items.length : 0,
  items: body.items || [],
  specialNotes: body.specialNotes || 'None',
  subtotal: body.subtotal || 0,
  tax: body.tax || 0,
  total: body.total || 0,
  status: 'Preparing',
  receivedAt: new Date().toISOString(),
  formattedTime: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
};

return [{
  json: orderSummary
}];
